-- ONE MORE DRAFT LISTING requested 27 November 2026. All hidden until checked and published in admin.
-- Skipped if a listing with the same name or slug already exists.

insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'statz-cricket', 'Statz Cricket', array['tool']::listing_type[], 'Cricket stats, match projections and bet builder tools for every major league and format.', 'The cricket side of Statz. Fixtures, results, player and team stats and ground records across T20 leagues such as the IPL and Big Bash, international cricket, county cricket and the Sheffield Shield. A match simulator produces projections and win chances, with hit rates, a stat finder, a bet builder and Dream11 team ratings. Free accounts get one fully projected match a day, with the rest behind a Pro tier.', 'https://statz.ai/cricket', 'freemium'::pricing_model, 'Free account, with a paid Pro tier; check current pricing', array['cricket']::text[], 'Stats and data', array['Free plan','Web app','iOS app','Android app','Projections','Player prop hit rates','Matchup data','Free picks','Fantasy rankings']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "DECISION NEEDED: the cricket pages show bookmaker odds and sign-up offers with affiliate links, including offshore books that are not licensed in Australia (1xBet, Dafabet, 1win) alongside bet365 and Ladbrokes. That is a bigger problem than the main Statz listing. Its Best Bets record (units, ROI) is self-reported; do not repeat it. If you list Statz at all, one listing covering football and cricket may be better than two. UK flag is a best guess; add Pro pricing.", "country": "GB", "categories": ["Stats and data", "Models and projections", "Player prop research"]}'::jsonb where not exists (select 1 from listings where lower(name) = lower('Statz Cricket')) on conflict (slug) do nothing;
insert into listing_links (listing_id, platform, url) select l.id, v.platform, v.url from listings l, (values ('Website','https://statz.ai/cricket'),('YouTube','https://www.youtube.com/@CricketBettingPodcast')) as v(platform,url) where l.slug = 'statz-cricket' and l.status = 'draft' and not exists (select 1 from listing_links k where k.listing_id = l.id);
